import{_ as a,C as r,c as n,o as i,a3 as t,G as o}from"./chunks/framework.Dokpd4od.js";const T=JSON.parse('{"title":"Timesheet settings","description":"","frontmatter":{},"headers":[],"relativePath":"master/services/timesheets/timesheet-settings.md","filePath":"master/services/timesheets/timesheet-settings.md","lastUpdated":1792041590000}'),l={name:"master/services/timesheets/timesheet-settings.md"};function h(g,e,m,d,p,c){const s=r("ImagePopup");return i(),n("div",null,[e[0]||(e[0]=t('<h1 id="timesheet-settings" tabindex="-1">Timesheet settings <a class="header-anchor" href="#timesheet-settings" aria-label="Permalink to &quot;Timesheet settings&quot;">​</a></h1><p>Do this page first. Nothing can be logged until the settings are on.</p><p>Timesheets work through three layers of switches and numbers. A global switch turns the feature on, a project switch lets that project take time, and <strong>Allocated Hours</strong> sets the plan. After this, Aureus shows spent time, remaining time and progress on every task.</p><blockquote><p><strong>In simple words:</strong> Switch it on once, allow it per project, set the planned hours, and the task totals follow.</p></blockquote><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><h3 id="enable-timesheets" tabindex="-1">Enable Timesheets <a class="header-anchor" href="#enable-timesheets" aria-label="Permalink to &quot;Enable Timesheets&quot;">​</a></h3><ol><li>Open <code>Project → Settings → Manage Time</code>.</li><li>Turn on <strong>Enable Timesheets</strong>. Its note reads &quot;Track time spent on projects and tasks&quot;.</li><li>Click <strong>Save changes</strong>.</li></ol>',7)),o(s,{src:"/images1/timesheets/ts_enable_timesheets.png",alt:"Manage Time settings page with Enable Timesheets turned on"}),e[1]||(e[1]=t('<p>This adds the time fields to projects and tasks and the time columns to the task list. See <a href="./../project/get-started/project-settings.html">Project settings</a>.</p><h3 id="allow-timesheets-on-a-project" tabindex="-1">Allow Timesheets on a project <a class="header-anchor" href="#allow-timesheets-on-a-project" aria-label="Permalink to &quot;Allow Timesheets on a project&quot;">​</a></h3><ol><li>Open <code>Project → Projects</code> and open the project, then click <strong>Edit</strong>.</li><li>In the <strong>Settings</strong> section, find the <strong>Time Management</strong> group.</li><li>Turn on <strong>Allow Timesheets</strong>. Its note reads &quot;Log time on tasks and track progress&quot;.</li><li>Save the project.</li></ol>',3)),o(s,{src:"/images1/timesheets/ts_allow_timesheets.png",alt:"Project settings section with Allow Timesheets turned on"}),e[2]||(e[2]=t('<p>This group shows only when <strong>Enable Timesheets</strong> is on. Without <strong>Allow Timesheets</strong>, the project&#39;s tasks hide the <strong>Timesheets</strong> tab.</p><h2 id="allocated-hours" tabindex="-1">Allocated Hours <a class="header-anchor" href="#allocated-hours" aria-label="Permalink to &quot;Allocated Hours&quot;">​</a></h2><p><strong>Allocated Hours</strong> is the time you plan. Type it in decimal hours. For example, 1.5 means 1 hour 30 minutes.</p><ul><li><strong>On a project:</strong> Set the total plan. <strong>Website Revamp</strong> has 120 hours. See <a href="./../project/project-management/create-project.html">Create a project</a>.</li><li><strong>On a task:</strong> Set the plan for that task. <strong>Migrate CMS content</strong> has 20 hours. See <a href="./../project/task-management/create-task.html">Create a task</a>.</li></ul>',4)),o(s,{src:"/images1/timesheets/ts_allocated_hours_task.png",alt:"Task form Settings section with Allocated Hours set to 20"}),e[3]||(e[3]=t('<p>The field appears only when <strong>Enable Timesheets</strong> is on.</p><h2 id="summary-rows-on-a-task" tabindex="-1">Summary rows on a task <a class="header-anchor" href="#summary-rows-on-a-task" aria-label="Permalink to &quot;Summary rows on a task&quot;">​</a></h2><p>Open a task, scroll down the <strong>View</strong> page and click the <strong>Timesheets</strong> tab. The <strong>Summary</strong> rows under the <strong>Time Spent</strong> column show:</p><ul><li><strong><em>Time Spent:</em></strong> Hours logged on this task.</li><li><strong><em>Time Spent on Subtasks:</em></strong> Hours logged on its sub tasks.</li><li><strong><em>Total Time Spent:</em></strong> Both added together.</li><li><strong><em>Remaining Time:</em></strong> <strong>Allocated Hours</strong> minus <strong>Total Time Spent</strong>. It shows only when the task has <strong>Allocated Hours</strong>.</li></ul>',4)),o(s,{src:"/images1/timesheets/ts_task_summary_rows.png",alt:"Summary rows under the Time Spent column on a task"}),e[4]||(e[4]=t('<h2 id="progress-and-its-colours" tabindex="-1">Progress and its colours <a class="header-anchor" href="#progress-and-its-colours" aria-label="Permalink to &quot;Progress and its colours&quot;">​</a></h2><p>The task view has a <strong>Time Tracking</strong> section with <strong>Allocated Time</strong>, <strong>Time Spent</strong>, <strong>Time Remaining</strong> and <strong>Progress</strong>. The task list also shows a <strong>Progress</strong> bar.</p><table tabindex="0"><thead><tr><th>Progress</th><th>Colour</th><th>Meaning</th></tr></thead><tbody><tr><td>Under 100%</td><td>Orange</td><td>Work is within the plan.</td></tr><tr><td>Exactly 100%</td><td>Green</td><td>The plan is used in full.</td></tr><tr><td>Over 100%</td><td>Red</td><td>The task is over its plan.</td></tr></tbody></table><p><strong>Progress</strong> can pass 100%. Remaining time then shows a negative number, as in the example below.</p>',4)),o(s,{src:"/images1/timesheets/ts_task_progress.png",alt:"Time Tracking section of Migrate CMS content with 25 hours spent, minus 5 remaining and 125 percent progress in red"}),e[5]||(e[5]=t('<h2 id="what-happens-after-each-save-or-delete" tabindex="-1">What happens after each save or delete <a class="header-anchor" href="#what-happens-after-each-save-or-delete" aria-label="Permalink to &quot;What happens after each save or delete&quot;">​</a></h2><p>Aureus recalculates the task after every entry you add, edit or delete.</p><ol><li>It adds the task&#39;s own entries to get <strong>Time Spent</strong>.</li><li>It adds the sub task entries to get <strong>Time Spent on Subtasks</strong>.</li><li>It subtracts the total from <strong>Allocated Hours</strong> to get <strong>Remaining Time</strong>.</li><li>It divides the total by <strong>Allocated Hours</strong> to get <strong>Progress</strong>.</li><li>If the task is a sub task, it does the same for the parent.</li></ol><p>The parent updates one level up.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Set <strong>Allocated Hours</strong> before people log time. A task with no planned hours has no <strong>Remaining Time</strong> and 0 <strong>Progress</strong>.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./">Timesheets overview</a></li><li><a href="./log-time.html">Log time</a></li><li><a href="./timesheet-list-and-filters.html">Timesheet list and filters</a></li><li><a href="./../project/get-started/project-settings.html">Project settings</a></li></ul>',7))])}const _=a(l,[["render",h]]);export{T as __pageData,_ as default};
